# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: "@" mentions of the session's variables in the chats (EXPERIMENTAL), with no UI code.
#          "@q1" in a message points at a variable: the AI gets a text block describing it
#          (a small value whole, a big one as shape, columns and first rows; the chat agent can
#          then query it with the query_variable tool), and a message that is only mentions
#          prints them with no AI call. "@r3.df" / "@q1.char" follow a dotted path; nothing is
#          ever called. An "@name" that isn't a variable is plain text.
#          Text only: nothing here keeps a value, so a cleared variable is still freed, and the
#          block is built again on every send (no cache).
# Usage: find(text, session) / context(text, session, tool) / bare(text, session) /
#        rows(session) / toolset(session); read by state.py (which also keeps rows() on the
#        page for assets/mentions.js: the list "@" opens), inline_fill.py and inline_edit.py.
# Spec:  spec/experimental/reflex-kernel/variables.md ("Mentions")
# ---------------------------------------------------------------------------
from __future__ import annotations

import inspect
import json
import re
from dataclasses import dataclass
from typing import TYPE_CHECKING, Any

import polars as pl
from ds.ai import TableResult
from pydantic import BaseModel
from pydantic_ai import ModelRetry
from pydantic_ai.toolsets import FunctionToolset

from . import perf
from .db_console import DbConsole
from .session import BUILTIN_NAMES
from .tool_forms import ToolRequest

if TYPE_CHECKING:
    from .session import Session

# "@name" or "@name.part.part". Not inside a word or after another "@" (an email, "@@x").
MENTION = re.compile(r"(?<![\w@])@([A-Za-z_]\w*(?:\.[A-Za-z_]\w*)*)")
# The hybrid rule: a value at most this big is given to the AI whole, a bigger one as a summary.
WHOLE_ROWS = 50
WHOLE_CHARS = 4000
SAMPLE_ROWS = 5  # rows shown of a table that is too big to send whole
MAX_COLUMNS = 40  # columns listed (and offered after "@name.") of one table
# rows query_variable gives back to the model (the DataFrame bound as r<n> is cut the same way)
MAX_ROWS = 200
PYTHON = "python"
TOOL_NAME = "query_variable"


@dataclass
class Mention:
    path: str
    """As written after the "@", eg "q1" or "r3.df" (only the part that names something)."""
    value: Any

    @property
    def root(self) -> str:
        return self.path.partition(".")[0]


def _names(session: Session) -> list[str]:
    """The names that can be mentioned: the user's variables, the Variables pane's rule
    (perf.user_variables), in the order bound."""
    listed = {name for name, _, _ in perf.user_variables(session.namespace, BUILTIN_NAMES)}
    return [name for name in session.namespace if name in listed]


def _step(value: Any, part: str) -> tuple[bool, Any]:
    """One part of a dotted path: (found, the value there). A table's column, a model's field, a
    dict's key, else an attribute. Never a private name, and never a method (nothing is called)."""
    if part.startswith("_"):
        return False, None
    if isinstance(value, pl.DataFrame) and part in value.columns:
        return True, value[part]
    if isinstance(value, dict) and part in value:
        return True, value[part]
    try:
        found = getattr(value, part)
    except Exception:  # noqa: BLE001  # no such attribute, or a property that raises: not a path
        return False, None
    if inspect.isroutine(found) or isinstance(found, type):
        return False, None
    return True, found


def resolve(session: Session, path: str) -> Mention | None:
    """The variable a path names, None when its first name isn't one. A path is followed as far
    as it names something: "@q1.Thanks" is q1 (the rest is the sentence going on)."""
    root, *parts = path.split(".")
    if root not in _names(session):
        return None
    value, taken = session.namespace[root], [root]
    for part in parts:
        found, there = _step(value, part)
        if not found:
            break
        value = there
        taken.append(part)
    return Mention(".".join(taken), value)


def find(text: str, session: Session | None) -> list[Mention]:
    """The variables a message mentions, each once, in the order written."""
    if session is None or "@" not in text:
        return []
    found: dict[str, Mention] = {}
    for match in MENTION.finditer(text):
        mention = resolve(session, match.group(1))
        if mention is not None:
            found.setdefault(mention.path, mention)
    return list(found.values())


def bare(text: str, session: Session | None) -> list[Mention] | None:
    """The mentions of a message that is nothing but mentions ("@q1", "@q1 @r2"): it prints them
    and no AI is asked. None for any other message, or when one of them isn't a variable."""
    words = text.split()
    if session is None or not words:
        return None
    found = []
    for word in words:
        match = MENTION.fullmatch(word)
        mention = resolve(session, match.group(1)) if match else None
        if mention is None or mention.path != word[1:]:
            return None
        found.append(mention)
    return found


def _cut(text: str, limit: int = WHOLE_CHARS) -> str:
    return text if len(text) <= limit else f"{text[:limit]}… (cut: {len(text):,} characters in all)"


def _table(df: pl.DataFrame, tool_hint: str) -> str:
    """A table for the model: whole as CSV when small, else its columns and first rows."""
    shape = f"polars DataFrame, {df.height:,} rows × {df.width} columns"
    csv = df.write_csv() if df.height <= WHOLE_ROWS else ""
    if csv and len(csv) <= WHOLE_CHARS:
        return f"{shape}, all of it as CSV:\n{csv}"
    columns = [f"{name} {dtype}" for name, dtype in df.schema.items()]
    more = f", ... {len(columns) - MAX_COLUMNS} more" if len(columns) > MAX_COLUMNS else ""
    lines = [
        f"{shape}. Too big to show whole: you only have what is below.",
        f"columns: {', '.join(columns[:MAX_COLUMNS])}{more}",
        f"first {min(SAMPLE_ROWS, df.height)} rows as CSV:",
        _cut(df.head(SAMPLE_ROWS).write_csv()),
    ]
    return "\n".join([*lines, tool_hint] if tool_hint else lines)


def _value(value: Any, tool_hint: str) -> str:
    match value:
        case pl.DataFrame():
            return _table(value, tool_hint)
        case pl.Series():
            return f"one column ({value.name!r}, {value.dtype}) as a table: {_table(value.to_frame(), tool_hint)}"
        case DbConsole():
            if value.df is None:
                return "SmashDb console, no query run yet"
            return f"SmashDb console. Its query:\n{value.sql}\nIts result: {_table(value.df, tool_hint)}"
        case ToolRequest():
            inputs = json.dumps(value.inputs, default=str, ensure_ascii=False)
            return f"the form of the tool {value.form}, not run yet. Inputs: {inputs}"
        case BaseModel():
            return f"{type(value).__name__} as JSON:\n{_cut(value.model_dump_json())}"
        case list() | tuple() | dict() | set():
            try:
                text = json.dumps(value, default=str, ensure_ascii=False)
            except (TypeError, ValueError):
                text = repr(value)
            return f"{type(value).__name__}, {len(value):,} items: {_cut(text)}"
        case _:
            return f"{type(value).__name__}: {_cut(repr(value))}"


def describe(mention: Mention, session: Session | None = None, tool: bool = False) -> str:
    """One mentioned variable as text for the model: what it is, where it came from, its value
    (the hybrid rule). tool: the reader has query_variable (the chat agent), so a big table
    says how to read the rest; an inline AI has no tools and is told only what it has."""
    hint = f'To read more of it, call {TOOL_NAME}("{mention.path}", "select ... from self").' if tool else ""
    source = session.sources.get(mention.root, PYTHON) if session else ""
    made = f" (made by: {source})" if source else ""
    return f"@{mention.path}{made}: {_value(mention.value, hint)}"


def context(text: str, session: Session | None, tool: bool = False) -> str:
    """The block added to what the model gets for a message with mentions, "" when it has none.
    The values as they are now: a later change to a variable doesn't change what was sent."""
    found = find(text, session)
    if not found:
        return ""
    intro = " ".join(
        [
            "Variables of the app's Python session that the user mentioned with @ in the message",
            "above, as they are right now:",
        ]
    )
    return "\n\n".join([intro, *[describe(mention, session, tool) for mention in found]])


def with_context(text: str, session: Session | None, tool: bool = False) -> str:
    """The message as the model gets it: itself, then the block about what it mentions."""
    return "\n\n".join(filter(None, [text, context(text, session, tool)]))


def _parts(value: Any) -> list[str]:
    """What can follow "@name.": a table's columns, a model's fields, a console's result."""
    match value:
        case pl.DataFrame():
            return value.columns[:MAX_COLUMNS]
        case DbConsole():
            return ["df", "sql"]
        case BaseModel():
            return list(type(value).model_fields)[:MAX_COLUMNS]
        case _:
            return []


def rows(session: Session | None) -> list[dict[str, Any]]:
    """The variables that can be mentioned, for the list "@" opens (assets/mentions.js): name,
    type, shape, source, and `parts` (what can follow "name.")."""
    if session is None:
        return []
    return [
        {
            "name": name,
            "type": type(session.namespace[name]).__name__,
            "shape": perf.shape_text(session.namespace[name]),
            "source": session.sources.get(name, PYTHON),
            "parts": _parts(session.namespace[name]),
        }
        for name in _names(session)
    ]


def _frame(value: Any) -> pl.DataFrame | None:
    match value:
        case pl.DataFrame():
            return value
        case pl.Series():
            return value.to_frame()
        case DbConsole():
            return value.df
        case _:
            return None


def toolset(session: Session) -> FunctionToolset[Any]:
    """The chat agent's tool for a mentioned table too big to send whole, given to it at run time
    (Session.ask): the agent in pkgs/ds/ai is not changed. It holds the session, never a value."""

    def query_variable(name: str, sql: str) -> TableResult:
        """Query a table variable of the app's Python session that the user mentioned with @.

        Use it when a mentioned variable was too big to be shown whole. Runs one polars SQL
        SELECT (PostgreSQL syntax) in which the variable is the table `self`.

        Args:
            name: the variable as mentioned, without the @, eg "q1" or "r3.df".
            sql: the query, eg "select player, wins from self order by wins desc limit 10".
        """
        mention = resolve(session, name.lstrip("@"))
        if mention is None:
            raise ModelRetry(f"There is no variable {name!r}. The variables are: {', '.join(_names(session))}")
        df = _frame(mention.value)
        if df is None:
            raise ModelRetry(f"{name} is a {type(mention.value).__name__}, not a table: it can't be queried.")
        try:
            result = df.sql(sql.strip().rstrip(";"))
        except Exception as error:  # noqa: BLE001  # whatever polars raises is what the model must fix
            raise ModelRetry(f"SQL error (polars SQL, the table is `self`): {error}") from error
        return TableResult.from_df(result, max_rows=MAX_ROWS)

    return FunctionToolset([query_variable])
